CREATE TABLE IF NOT EXISTS `settings` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT UNIQUE, `name` varchar(255) NOT NULL UNIQUE, `foundation_id` bigint NOT NULL, `unit_id` bigint NOT NULL, `academic_year_id` bigint NOT NULL, `start_date` date NOT NULL, `end_date` date NOT NULL, `created_at` timestamp NOT NULL, `is_active` tinyint NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` datetime );
CREATE TABLE IF NOT EXISTS `sports` ( `id` bigint NOT NULL PRIMARY KEY, `code` varchar(255) NOT NULL UNIQUE, `name` varchar(255) NOT NULL, `description` text, `config_schema` json, `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` timestamp );
CREATE TABLE IF NOT EXISTS `student_enrollments` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `student_id` bigint NOT NULL, `class_id` bigint NOT NULL, `academic_year_id` bigint NOT NULL, `enrollment_date` date NOT NULL, `status` ENUM('active', 'transferred', 'graduated', 'dropped'), `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL );
CREATE TABLE IF NOT EXISTS `students` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `user_id` bigint NOT NULL UNIQUE, `name` varchar(255) NOT NULL, `foundation_id` bigint NOT NULL, `unit_id` bigint, `student_number` varchar(255) NOT NULL, `class_id` bigint, `parent_name` varchar(255), `parent_phone` varchar(255), `enrollment_date` timestamp, `graduation_date` timestamp, `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` timestamp, CONSTRAINT `fk-students-user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT );
CREATE TABLE IF NOT EXISTS `subject_preferences` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `subject_id` bigint NOT NULL, `time_slot_id` bigint NOT NULL, `preference_level` ENUM('preferred', 'neutral', 'avoid'), `reason` varchar(255), `created_at` timestamp NOT NULL );
CREATE TABLE IF NOT EXISTS `subject_room_requirements` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `subject_id` bigint NOT NULL, `required_room_type` ENUM('classroom', 'lab', 'hall', 'library', 'outdoor') NOT NULL, `required_facilities` json, `created_at` timestamp NOT NULL );
CREATE TABLE IF NOT EXISTS `subjects` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `foundation_id` bigint NOT NULL, `code` varchar(255), `name` varchar(255) NOT NULL, `description` text, `credit_hours` int, `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` timestamp );
CREATE TABLE IF NOT EXISTS `teacher_assignments` ( `id` bigint NOT NULL PRIMARY KEY, `teacher_id` bigint NOT NULL, `unit_id` bigint NOT NULL, `academic_year_id` bigint NOT NULL, `employment_status` varchar(255) NOT NULL, `employment_type` varchar(255) NOT NULL, `position` varchar(255) NOT NULL, `position_level` varchar(255), `department_id` bigint, `teaching_hours_per_week` int, `max_teaching_hours` int, `assignment_start_date` date NOT NULL, `assignment_end_date` date, `is_active` tinyint, `notes` text, `created_at` timestamp, `updated_at` timestamp, CONSTRAINT `fk-teacher_assignments-academic_year_id` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_assignments-department_id` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_assignments-teacher_id` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_assignments-unit_id` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION );
CREATE TABLE IF NOT EXISTS `teacher_availability` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `teacher_id` bigint NOT NULL, `time_slot_id` bigint NOT NULL, `is_available` tinyint, `reason` varchar(255), `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL );
CREATE TABLE IF NOT EXISTS `teacher_salaries` ( `id` bigint NOT NULL PRIMARY KEY, `teacher_assignment_id` bigint NOT NULL, `salary_grade_id` bigint NOT NULL, `base_salary` decimal(15, 2) NOT NULL, `position_allowance` decimal(15, 2), `teaching_allowance` decimal(15, 2), `certification_allowance` decimal(15, 2), `performance_allowance` decimal(15, 2), `transport_allowance` decimal(15, 2), `meal_allowance` decimal(15, 2), `other_allowances` decimal(15, 2), `tax_deduction` decimal(15, 2), `insurance_deduction` decimal(15, 2), `loan_deduction` decimal(15, 2), `other_deductions` decimal(15, 2), `gross_salary` decimal(15, 2), `net_salary` decimal(15, 2), `effective_date` date NOT NULL, `notes` text, `created_at` timestamp, `updated_at` timestamp, CONSTRAINT `fk-teacher_salaries-salary_grade_id` FOREIGN KEY (`salary_grade_id`) REFERENCES `salary_grades` (`id`) ON DELETE RESTRICT ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_salaries-teacher_assignment_id` FOREIGN KEY (`teacher_assignment_id`) REFERENCES `teacher_assignments` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION );
CREATE TABLE IF NOT EXISTS `teacher_subjects` ( `id` bigint NOT NULL PRIMARY KEY, `teacher_assignment_id` bigint NOT NULL, `subject_id` bigint NOT NULL, `classroom_id` bigint NOT NULL, `academic_year_id` bigint NOT NULL, `semester_id` bigint, `hours_per_week` int, `is_active` tinyint, `assigned_at` date NOT NULL, `created_at` timestamp, `updated_at` timestamp, CONSTRAINT `fk-teacher_subjects-academic_year_id` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_subjects-classroom_id` FOREIGN KEY (`classroom_id`) REFERENCES `classrooms` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_subjects-semester_id` FOREIGN KEY (`semester_id`) REFERENCES `semesters` (`id`) ON DELETE SET NULL ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_subjects-subject_id` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_subjects-teacher_assignment_id` FOREIGN KEY (`teacher_assignment_id`) REFERENCES `teacher_assignments` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION );
CREATE TABLE IF NOT EXISTS `teachers` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `user_id` bigint NOT NULL UNIQUE, `name` varchar(255) NOT NULL, `foundation_id` bigint NOT NULL, `unit_id` bigint, `nik` varchar(255), `employee_number` varchar(255) NOT NULL, `specialization` varchar(255), `qualification` varchar(255), `teacher_assignment_id` bigint, `hire_date` date, `end_date` date, `salary` varchar(255), `employment_status` ENUM('permanent', 'contract', 'freelance'), `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` timestamp, CONSTRAINT `fk-teachers-teacher_assignment_id` FOREIGN KEY (`teacher_assignment_id`) REFERENCES `teacher_assignments` (`id`), CONSTRAINT `fk-teachers-user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT );
CREATE TABLE IF NOT EXISTS `teacher_subjects` ( `id` bigint NOT NULL PRIMARY KEY, `academic_year_id` bigint NOT NULL, `teacher_assignment_id` bigint NOT NULL, `is_active` tinyint, `assigned_at` date NOT NULL, `created_at` timestamp, `updated_at` timestamp, CONSTRAINT `fk-teacher_subjects-academic_year_id` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION, CONSTRAINT `fk-teacher_subjects-teacher_assignment_id` FOREIGN KEY (`teacher_assignment_id`) REFERENCES `teacher_assignments` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION );
CREATE TABLE IF NOT EXISTS `time_slots` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `foundation_id` bigint NOT NULL, `name` varchar(255) NOT NULL, `day_of_week` tinyint NOT NULL, `start_time` time NOT NULL, `end_time` time NOT NULL, `slot_type` ENUM('lesson', 'break', 'extracurricular'), `order` int NOT NULL, `is_active` tinyint, `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` text );
CREATE TABLE IF NOT EXISTS `unit_types` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT UNIQUE, `foundation_id` bigint NOT NULL, `name` varchar(255) NOT NULL UNIQUE, `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` text );
CREATE TABLE IF NOT EXISTS `units` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT UNIQUE, `name` varchar(255) NOT NULL, `foundation_id` bigint NOT NULL, `unit_type_id` varchar(255), `class_level_id` int, `level_id` bigint NOT NULL, `parent_id` bigint NOT NULL, `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` text );
CREATE TABLE IF NOT EXISTS `universities` ( `id` bigint NOT NULL PRIMARY KEY, `code` varchar(255) NOT NULL UNIQUE, `name` varchar(255) NOT NULL, `description` text, `config_schema` json, `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` timestamp );
CREATE TABLE IF NOT EXISTS `user_permissions` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT UNIQUE, `user_id` bigint NOT NULL, `permission_id` bigint NOT NULL, `foundation_id` bigint NOT NULL, `created_at` timestamp NOT NULL, `deleted_at` text, CONSTRAINT `fk-user_permissions-foundation_id` FOREIGN KEY (`foundation_id`) REFERENCES `foundations` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION, CONSTRAINT `fk-user_permissions-user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`), CONSTRAINT `fk-user_permissions-permission_id` FOREIGN KEY (`permission_id`) REFERENCES `permissions` (`id`) );
CREATE TABLE IF NOT EXISTS `user_profiles` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `foundation_id` bigint NOT NULL, `user_id` bigint NOT NULL UNIQUE, `phone` varchar(255), `dob` date, `pob` varchar(255), `bio` text, `avatar` varchar(255), `gender` ENUM('m', 'f'), `address` text, `city` varchar(255), `province` varchar(255), `country` varchar(255), `postal_code` varchar(255), `latitude` varchar(255), `longitude` varchar(255), `timezone` varchar(255), `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` text, CONSTRAINT `fk-user_profiles-user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT );
CREATE TABLE IF NOT EXISTS `users` ( `id` bigint NOT NULL PRIMARY KEY AUTO_INCREMENT, `name` varchar(255) NOT NULL, `email` varchar(255) NOT NULL UNIQUE, `foundation_id` bigint NOT NULL, `username` varchar(255), `password` varchar(255) NOT NULL, `is_verified` tinyint, `is_active` tinyint, `avatar` varchar(255), `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, `deleted_at` text );
SET FOREIGN_KEY_CHECKS = 1;
